export default {
  safeParse(s) {
    try {
      if (!s) return {};
      if (typeof s === 'object') return s;
      return JSON.parse(s);
    } catch (e) {
      return { _raw: s, _error: String(e) };
    }
  },

  durationDays(interval) {
    // Postgres interval often comes back as string like "3 days 04:12:00"
    if (!interval) return "";
    const s = String(interval);
    const m = s.match(/(-?\d+)\s+days?/i);
    if (m) return m[1];
    // try HH:MM:SS only
    return s;
  },

  monthlyYieldChartData(rows) {
    const data = (rows || []).map(r => ({ x: r.month, y: Number(r.total_harvest_g || 0) }));
    return { series: [{ seriesName: "Total harvest (g)", data }] };
  },

  contamMonthlyChartData(rows) {
    const data = (rows || []).map(r => ({ x: r.month, y: Number(r.contamination_rate || 0) }));
    return { series: [{ seriesName: "Contamination rate", data }] };
  },

  async init() {
    await storeValue('selectedLotId', appsmith.store.selectedLotId || null);
    await storeValue('selectedEventId', null);
    await Promise.allSettled([
      qLotsSearch.run(),
      qSpeciesOptions.run(),
      qGrainOptions.run(),
      qSubstrateOptions.run()
    ]);

    // If a lot is already selected (deep link / previous state), load its details
    if (appsmith.store.selectedLotId) {
      await Promise.allSettled([qEventsForLot.run(), qLotMetrics.run()]);
    }
  },

  async applyAnalytics() {
    await Promise.allSettled([
      qCohortCycleTimes.run(),
      qContamIncidencePerItem.run(),
      qMonthlyHarvestYield.run(),
      qContamIncidenceMonthly.run(),
      qCohortOutliers.run()
    ]);
  }
};

