async function () {
  const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
  if (!rows.length) {
    showAlert("No lots selected", 'error');
    await storeValue('lots_error', "No lots selected");
    return false;
  }
  let retval = true;
  for (const v of rows) {
    if (!v.inoculated_at) {
      showAlert(v.lot_id + " must be inoculated to shake.", 'error');
      retval = false;
    }
    if (v.item_category_mat !== 'grain') {
      showAlert(v.lot_id + " must be a grain to shake.", 'error');
      retval = false;
    }
  }
  return retval;
}

